package com.nexus.event; import org.springframework.stereotype.Component; import org.springframework.beans.factory.annotation.Value; import com.nexus.data.NoticeRepository; import com.nexus.domain.Notice;
@Component public class EmailNotification implements NotificationChannel{private final NoticeRepository repo;private final boolean live;public EmailNotification(NoticeRepository r,@Value("${nexus.email.enabled}") boolean live){repo=r;this.live=live;}public void deliver(IncidentEvent e,Long u){repo.save(new Notice(u,e.incidentId(),e.at(),"EMAIL",live?"PENDING":"SIMULATED",e.action()+" · INC-"+e.incidentId()));}}
